-- Run after V5. Every query should return zero rows. Read-only and repeatable.
SELECT 'role instance boundary' AS problem,r.id FROM sys_role r LEFT JOIN sys_tenant_application ta ON ta.id=r.tenant_application_id AND ta.tenant_id=r.tenant_id AND ta.application_id=r.application_id WHERE ta.id IS NULL;
SELECT 'user role boundary' AS problem,ur.id FROM sys_user_role ur LEFT JOIN sys_user u ON u.id=ur.user_id AND u.tenant_id=ur.tenant_id LEFT JOIN sys_role r ON r.id=ur.role_id AND r.tenant_id=ur.tenant_id AND r.application_id=ur.application_id AND r.tenant_application_id=ur.tenant_application_id WHERE u.id IS NULL OR r.id IS NULL;
SELECT 'permission application boundary' AS problem,rp.id FROM sys_role_permission rp LEFT JOIN sys_role r ON r.id=rp.role_id AND r.tenant_id=rp.tenant_id AND r.application_id=rp.application_id AND r.tenant_application_id=rp.tenant_application_id LEFT JOIN sys_permission p ON p.id=rp.permission_id AND p.application_id=rp.application_id WHERE r.id IS NULL OR p.id IS NULL;
SELECT 'menu application boundary' AS problem,m.id FROM sys_menu m LEFT JOIN sys_menu p ON p.id=m.parent_id AND p.application_id=m.application_id WHERE m.parent_id<>0 AND p.id IS NULL;
SELECT 'duplicate active instance' AS problem,tenant_id,application_id,COUNT(*) FROM sys_tenant_application WHERE is_delete=0 GROUP BY tenant_id,application_id HAVING COUNT(*)>1;
SELECT 'tenant without console' AS problem,t.id FROM sys_tenant t LEFT JOIN sys_tenant_application ta ON ta.tenant_id=t.id AND ta.application_id=1 AND ta.is_delete=0 WHERE ta.id IS NULL;
SELECT 'invalid grant' AS problem,ua.id FROM sys_user_application ua LEFT JOIN sys_user u ON u.id=ua.user_id AND u.tenant_id=ua.tenant_id LEFT JOIN sys_tenant_application ta ON ta.id=ua.tenant_application_id AND ta.tenant_id=ua.tenant_id WHERE u.id IS NULL OR ta.id IS NULL;
